//! Replays `fixtures/git-core.jsonl`, generated by `rust/tools/generate_vcs_git_core_fixtures.mjs`
//! from the original GitVcsDriverCore.ts and git/remoteRefs.ts.
use serde_json::{Value, json};
use t3_vcs::{
    core::{
        classify_git_failure, derive_local_branch_name_from_remote_ref, is_missing_worktree_stderr,
        is_non_repository_stderr, is_unborn_head_stderr, parse_git_checkout_progress_line,
        parse_remote_names_in_git_order, parse_remote_ref_with_remote_names,
        parse_tracking_branch_by_upstream_ref, sorted_longest_first,
    },
    git::split_null_separated_paths,
    status::{
        parse_branch_ab, parse_default_branch_from_remote_head_ref, parse_numstat_entries,
        parse_porcelain_path,
    },
};

fn rows(kind: &str) -> Vec<Value> {
    include_str!("fixtures/git-core.jsonl")
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|row| row["type"] == kind)
        .collect()
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|item| item.as_str().unwrap().to_string())
        .collect()
}

#[test]
fn stderr_classification_matches_the_original() {
    let rows = rows("stderr");
    assert_eq!(rows.len(), 38);
    for row in rows {
        let stderr = row["stderr"].as_str().unwrap();
        let reason = classify_git_failure(stderr).map(|reason| reason.as_str());
        assert_eq!(json!(reason), row["reason"], "{stderr:?}");
        assert_eq!(
            is_non_repository_stderr(stderr),
            row["nonRepository"],
            "{stderr:?}"
        );
        assert_eq!(
            is_unborn_head_stderr(stderr),
            row["unbornHead"],
            "{stderr:?}"
        );
        assert_eq!(
            is_missing_worktree_stderr(stderr),
            row["missingWorktree"],
            "{stderr:?}"
        );
    }
}

#[test]
fn checkout_progress_lines_match_the_original() {
    let rows = rows("progress");
    assert_eq!(rows.len(), 7);
    for row in rows {
        let actual = parse_git_checkout_progress_line(row["line"].as_str().unwrap())
            .map(|(percent, completed, total)| json!({ "percent": percent, "completed": completed, "total": total }));
        assert_eq!(json!(actual), row["result"], "{row}");
    }
}

#[test]
fn branch_name_helpers_match_the_original() {
    for row in rows("tracking") {
        let actual = parse_tracking_branch_by_upstream_ref(
            row["stdout"].as_str().unwrap(),
            row["upstream"].as_str().unwrap(),
        );
        assert_eq!(json!(actual), row["result"], "{row}");
    }
    for row in rows("localName") {
        assert_eq!(
            json!(derive_local_branch_name_from_remote_ref(
                row["name"].as_str().unwrap()
            )),
            row["result"],
            "{row}"
        );
    }
    for row in rows("defaultBranch") {
        let actual = parse_default_branch_from_remote_head_ref(
            row["value"].as_str().unwrap(),
            row["remote"].as_str().unwrap(),
        );
        assert_eq!(json!(actual), row["result"], "{row}");
    }
}

#[test]
fn status_parsers_match_the_original() {
    for row in rows("ab") {
        let (ahead, behind) = parse_branch_ab(row["value"].as_str().unwrap());
        assert_eq!(
            json!({ "ahead": ahead, "behind": behind }),
            row["result"],
            "{row}"
        );
    }
    for row in rows("numstatEntries") {
        let actual: Vec<Value> = parse_numstat_entries(row["stdout"].as_str().unwrap())
            .into_iter()
            .map(|entry| json!({ "path": entry.path, "insertions": entry.insertions, "deletions": entry.deletions }))
            .collect();
        assert_eq!(Value::Array(actual), row["result"], "{row}");
    }
    for row in rows("porcelainPath") {
        assert_eq!(
            json!(parse_porcelain_path(row["line"].as_str().unwrap())),
            row["result"],
            "{row}"
        );
    }
}

#[test]
fn path_and_remote_parsing_match_the_original() {
    for row in rows("nullPaths") {
        let actual = split_null_separated_paths(
            row["input"].as_str().unwrap(),
            row["truncated"].as_bool().unwrap(),
        );
        assert_eq!(json!(actual), row["result"], "{row}");
    }
    for row in rows("remoteNames") {
        let in_order = parse_remote_names_in_git_order(row["stdout"].as_str().unwrap());
        assert_eq!(json!(in_order), row["inGitOrder"], "{row}");
        assert_eq!(
            json!(sorted_longest_first(in_order)),
            row["longestFirst"],
            "{row}"
        );
    }
    for row in rows("remoteRef") {
        let names = strings(&row["names"]);
        let actual = parse_remote_ref_with_remote_names(row["reference"].as_str().unwrap(), &names)
            .map(|(remote, branch)| json!({ "remoteName": remote, "branchName": branch }));
        let expected = if row["result"].is_null() {
            Value::Null
        } else {
            json!({ "remoteName": row["result"]["remoteName"], "branchName": row["result"]["branchName"] })
        };
        assert_eq!(json!(actual), expected, "{row}");
    }
}
